def max_water_between_walls(heights):
    if len(heights) < 2:
        return 0
    left, right = 0, len(heights) - 1
    best = 0
    while left < right:
        area = min(heights[left], heights[right]) * (right - left)
        if area > best:
            best = area
        if heights[left] <= heights[right]:
            left += 1
        else:
            right -= 1
    return best
